class Solution {
public:
    int maximumScore(vector<int>& scores, vector<vector<int>>& edges) {
        int n = scores.size();
        vector<vector<int>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        vector<vector<int>> top3(n);
        for (int i = 0; i < n; i++) {
            sort(adj[i].begin(), adj[i].end(), [&](int a, int b) {
                return scores[a] > scores[b];
            });
            if (adj[i].size() > 3) adj[i].resize(3);
            top3[i] = adj[i];
        }
        int ans = -1;
        for (const auto& e : edges) {
            int u = e[0], v = e[1];
            for (int a : top3[u]) {
                for (int b : top3[v]) {
                    if (a != v && b != u && a != b) {
                        ans = max(ans, scores[a] + scores[u] + scores[v] + scores[b]);
                    }
                }
            }
        }
        return ans;
    }
};

class Solution {
    public int maximumScore(int[] scores, int[][] edges) {
        int n = scores.length;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }
        List<List<Integer>> top3 = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            List<Integer> neighbors = adj.get(i);
            neighbors.sort((a, b) -> Integer.compare(scores[b], scores[a]));
            if (neighbors.size() > 3) {
                neighbors = new ArrayList<>(neighbors.subList(0, 3));
            }
            top3.add(neighbors);
        }
        int ans = -1;
        for (int[] e : edges) {
            int u = e[0], v = e[1];
            for (int a : top3.get(u)) {
                for (int b : top3.get(v)) {
                    if (a != v && b != u && a != b) {
                        ans = Math.max(ans, scores[a] + scores[u] + scores[v] + scores[b]);
                    }
                }
            }
        }
        return ans;
    }
}

/**
 * @param {number[]} scores
 * @param {number[][]} edges
 * @return {number}
 */
var maximumScore = function(scores, edges) {
    const n = scores.length;
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }
    const top3 = [];
    for (let i = 0; i < n; i++) {
        adj[i].sort((a, b) => scores[b] - scores[a]);
        top3.push(adj[i].slice(0, 3));
    }
    let ans = -1;
    for (const [u, v] of edges) {
        for (const a of top3[u]) {
            for (const b of top3[v]) {
                if (a !== v && b !== u && a !== b) {
                    const score = scores[a] + scores[u] + scores[v] + scores[b];
                    if (score > ans) ans = score;
                }
            }
        }
    }
    return ans;
};
